import {PATH,COLORS,SAFE,START_INDEX,HOMES,BASES,location as tokenLocation,newGame,legalMoves,resolveMove,roll,chooseBotMove,activePlayers} from './engine.js';
const root=document.querySelector('#app');
const labels=['Red','Green','Yellow','Blue'];
const COLOR_EMOJI=['🔴','🟢','🟡','🔵'];
const faces=[['front',1],['back',6],['right',3],['left',4],['top',2],['bottom',5]];
const pipLookup={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};
const angles={1:[0,0],2:[-90,0],3:[0,-90],4:[0,90],5:[90,0],6:[0,180]};
const KEY='jovenra:ludo:classic:v5';
let view='splash',dialog='',selection={kind:'computer',players:2,mode:'classic',color:3},game=null,dieValue=1,lastRoll=null,rolling=false,moving=false,tipShown=false,tipVisible=false,music=true,musicVolume=.80,effects=true,botTimer=null,qaNext=null,saveTimer=null,ambientStarted=false,challengeId=null,trophyRound=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
try{const s=JSON.parse(localStorage.getItem('jovenra:ludo:preferences')||'{}');music=s.music!==false;effects=s.effects!==false;musicVolume=Number.isFinite(s.musicVolume)?Math.max(0,Math.min(1,s.musicVolume)):.80;}catch{}
let saved=null;try{const d=JSON.parse(localStorage.getItem(KEY)||'null');if(d?.game&&d?.selection)saved=d}catch{}
const RECORD_KEY='jovenra:ludo:v6:records';let records={wins:0,completed:[],streak:0,lastClaim:'',stars:0,cups:0};try{const d=JSON.parse(localStorage.getItem(RECORD_KEY)||'{}');records={...records,...d,completed:Array.isArray(d.completed)?d.completed:[]}}catch{}
function saveRecords(){try{localStorage.setItem(RECORD_KEY,JSON.stringify(records))}catch{}}
const CHALLENGES=[{id:'first-capture',name:'FIRST CAPTURE',icon:'🎯',mode:'capture',desc:'Defeat the computer by capturing a rival token.',tag:'SKILL'},{id:'speed-run',name:'SPEED FINISH',icon:'⚡',mode:'quick',desc:'Bring your first token home to win the sprint.',tag:'RACE'},{id:'double-finish',name:'DOUBLE FINISH',icon:'🏆',mode:'popular',desc:'Get two tokens home before the computer.',tag:'MASTER'}];
const MODE_GOALS={classic:'All four tokens home',quick:'First token home wins',capture:'Capture one rival token',popular:'Two tokens home to win',mask:'Capture a rival, then bring one token home'};
const wait=ms=>new Promise(r=>setTimeout(r,ms));
const colorVars={red:'#e72943',green:'#14b65b',yellow:'#ffe031',blue:'#25afe2'};
function svgIcon(type){return type==='back'?'‹':type==='gear'?'⚙':type==='sound'?'♫':'⚅'}
function diceTransform(n){const [x,y]=angles[n]||angles[1];return `rotateX(${x}deg) rotateY(${y}deg) rotateZ(0deg)`}
function dieHtml(n){return `<span class="die-perspective"><span class="die-bouncer"><span class="die-cube" data-die="${n}" style="transform:${diceTransform(n)}">${faces.map(([side,val])=>`<span class="die-face face-${side}" data-pips="${val}"><span class="pips">${Array.from({length:9},(_,k)=>`<i class="pip ${pipLookup[val].includes(k)?'on':''}"></i>`).join('')}</span></span>`).join('')}</span></span></span>`}
function header(inMatch=false){return `<header class="topbar"><a class="brand" href="#" data-action="home" aria-label="Jovenra Ludo home"><span class="brand-mark">⚄</span><span class="brand-text"><b>JOVENRA</b><small>LUDO CLUB</small></span></a><div class="top-actions"><span class="head-chip">✦ FREE PLAY</span><button class="iconbtn" data-action="audio" aria-label="${music?'Mute':'Unmute'} background music" title="Music ${music?'on':'off'}">${music?'♫':'♪̸'}</button><button class="iconbtn" data-action="settings" aria-label="Open settings" title="Settings">⚙</button>${inMatch?'<button class="iconbtn" data-action="pause" aria-label="Pause game">☰</button>':''}</div></header>`}
function footer(){return `<footer class="footer-strip">Jovenra Ludo · Free local play · Original game artwork and audio</footer>`}
function logo(){return `<div class="intro-logo"><div class="royal-crown">♛</div><div class="game-word"><span>L</span><span>U</span><span>D</span><span>O</span></div><div class="game-sub">JOVENRA CLUB</div><div class="logo-board"><div class="r">●</div><div class="g">●</div><div class="b">●</div><div class="y">●</div></div></div>`}
function lobby(){return `<div class="scene">${header()}<main class="shell lobby">${logo()}<section class="lobby-actions"><h1>Ready to roll?</h1><p>Bright, fast-paced Ludo with local games, challenges, and computer rivals.</p><div class="action-row"><button data-action="computer" class="menu-tile"><span class="tile-emoji">🤖</span><b>VS COMPUTER</b><span>Challenge the bots</span></button><button data-action="pass" class="menu-tile"><span class="tile-emoji">👥</span><b>PASS & PLAY</b><span>Friends on one screen</span></button></div><div class="lobby-extras"><button data-action="challenges" class="lobby-extra"><strong>🎯 CHALLENGES</strong><small>Three offline objectives</small></button><button data-action="cup" class="lobby-extra"><strong>🏆 TROPHY CUP</strong><small>Three-round local cup</small></button><button data-action="daily" class="lobby-extra"><strong>🌟 DAILY BONUS</strong><small>Claim your free star</small></button><button data-action="achievements" class="lobby-extra"><strong>🎖️ MY BADGES</strong><small>Progress on this device</small></button></div><div class="smallrow"><button class="pill-outline" data-action="guide">📖 HOW TO PLAY</button><button class="pill-outline" data-action="settings">⚙ SETTINGS</button></div>${saved?'<div class="resume-row"><button class="btn-primary" data-action="resume">↻ CONTINUE MATCH</button></div>':''}</section></main>${footer()}</div>`}
function splash(){return `<div class="scene">${header()}<div class="splash-screen"><div class="splash-inner"><div class="royal-crown">♛</div><div class="splash-text">JOVENRA</div><div class="splash-sub">L U D O</div><div class="splash-dots">● ● ●</div></div></div></div>`}
function item(label,value,desc,current,group,emoji){return `<button class="choice ${current===value?'selected':''}" data-option="${group}:${value}"><span class="emoji">${emoji}</span><b>${label}</b><small>${desc}</small></button>`}
function selectMode(){return `<div class="scene">${header()}<main class="screen-main"><div class="back-nav"><button data-action="home">‹ BACK</button> GAME SETUP</div><section class="panel"><h1 class="panel-title">SELECT PLAYERS</h1><p class="panel-desc">${selection.kind==='computer'?'Play against computer challengers':'Everyone takes turns on the same device'}</p><div class="choice-group"><div class="group-label">NUMBER OF PLAYERS</div><div class="choices">${item('2 PLAYERS','2','A faster duel',String(selection.players),'players','👥')}${item('4 PLAYERS','4','A full house',String(selection.players),'players','👨‍👩‍👧‍👦')}</div></div><div class="choice-group"><div class="group-label">SELECT GAME</div><div class="choices modes-grid">${item('CLASSIC','classic','All four tokens home',selection.mode,'mode','🏆')}${item('QUICK','quick','First token home',selection.mode,'mode','⚡')}${item('1 KILL WIN','capture','First capture wins',selection.mode,'mode','🎯')}${item('POPULAR','popular','Two tokens home',selection.mode,'mode','🥇')}${item('MASK','mask','Capture + finish',selection.mode,'mode','🎭')}</div></div><p class="helper">POPULAR and MASK are original, offline rule variants. No online opponents, purchases or ads.</p><div class="cta-row"><button class="btn-primary" data-action="next-color">NEXT ➜</button></div></section></main>${footer()}</div>`}
function pawn(color){return `<span class="simple-pawn pawn-${color}" aria-hidden="true"><svg class="pawn-svg" viewBox="0 0 60 80" focusable="false" aria-hidden="true"><ellipse cx="30" cy="75" rx="24" ry="4" fill="#021b41" opacity=".34"/><ellipse cx="30" cy="68" rx="23" ry="9" fill="var(--pawn-dark)" stroke="#17334f" stroke-width="1.7"/><ellipse cx="30" cy="65" rx="20" ry="6.5" fill="var(--pawn)"/><path d="M25 30 C23 39 19 48 14 58 C11 64 15 68 20 69 L40 69 C47 68 49 64 46 58 C41 47 37 39 35 30 Z" fill="var(--pawn-dark)" stroke="#143453" stroke-width="1.5"/><path d="M25 32 C22 41 20 51 17 60 Q15 65 22 65 H38 Q44 64 42 60 C39 47 36 38 34 32Z" fill="var(--pawn)"/><path d="M25 37 Q22 47 21 57" fill="none" stroke="var(--pawn-light)" stroke-width="5" stroke-linecap="round" opacity=".58"/><ellipse cx="30" cy="18.5" rx="15" ry="15.5" fill="var(--pawn-dark)" stroke="#193f61" stroke-width="1.6"/><circle cx="30" cy="18" r="13.5" fill="var(--pawn)"/><ellipse cx="26" cy="13" rx="7.8" ry="6.6" fill="var(--pawn-light)" opacity=".79"/><ellipse cx="27" cy="30" rx="8" ry="3" fill="var(--pawn-dark)" opacity=".6"/><ellipse cx="30" cy="67" rx="16.5" ry="3" fill="var(--pawn-light)" opacity=".5"/></svg></span>`}
function selectColor(){return `<div class="scene">${header()}<main class="screen-main"><div class="back-nav"><button data-action="back-mode">‹ BACK</button> GAME SETUP</div><section class="panel"><h1 class="panel-title">SELECT TOKEN COLOR</h1><p class="panel-desc">Pick your side of the board. The computer uses another color.</p><div class="choice-group"><div class="group-label">YOUR COLOR</div><div class="color-choices">${COLORS.map((c,i)=>`<button class="color-option ${selection.color===i?'selected':''}" data-option="color:${i}" aria-label="${labels[i]} token">${pawn(c)}</button>`).join('')}</div></div><div class="choice-group"><div class="group-label">MATCH DETAILS</div><div class="mode-summary"><span class="mode-chip">${selection.kind==='computer'?'VS COMPUTER':'PASS & PLAY'}</span><span class="mode-chip">${selection.players} PLAYERS</span><span class="mode-chip">${selection.mode.toUpperCase()}</span></div><div class="center" style="font-size:13px;color:#d9f1ff">${COLOR_EMOJI[selection.color]} You play ${labels[selection.color]}</div></div><div class="cta-row"><button class="btn-primary" data-action="start">▶ PLAY</button></div></section></main>${footer()}</div>`}
function guide(){return `<div class="scene">${header()}<main class="screen-main"><div class="back-nav"><button data-action="home">‹ BACK</button> HELP</div><section class="panel"><h1 class="panel-title">HOW TO PLAY</h1><div class="fancy-divider">⚄ ⚅ ⚃</div><ol class="rule-list"><li>Tap your dice when it is your turn.</li><li>Roll a <b>six</b> to take a token out of its home base.</li><li>Tap a glowing token. It hops the number of cells you rolled.</li><li>Land on an opponent to send their token home. Star cells are safe.</li><li>A six gives you another turn, but three sixes in a row end your turn.</li><li>Classic: bring all four tokens home. Quick: bring one home. 1 Kill Win: capture a rival to win.</li></ol><div class="cta-row"><button class="btn-primary" data-action="computer">LET'S PLAY ➜</button></div></section></main>${footer()}</div>`}
function challenges(){return `<div class="scene">${header()}<main class="screen-main"><div class="back-nav"><button data-action="home">‹ BACK</button> OFFLINE CHALLENGES</div><section class="panel"><h1 class="panel-title">CHALLENGE ARENA</h1><p class="panel-desc">Pick a challenge and play against the computer. Every medal is earned on this device.</p><div class="challenge-grid">${CHALLENGES.map(c=>`<button class="challenge-card" data-challenge="${c.id}"><span class="challenge-icon">${c.icon}</span><span class="challenge-detail"><b>${c.name}</b><small>${c.desc}</small><em>${records.completed.includes(c.id)?'✓ COMPLETED':'PLAY CHALLENGE ➜'}</em></span></button>`).join('')}</div><div class="cta-row"><button class="btn-secondary" data-action="achievements">VIEW BADGES</button></div></section></main>${footer()}</div>`}
function trophy(){return `<div class="scene">${header()}<main class="screen-main"><div class="back-nav"><button data-action="home">‹ BACK</button> TROPHY CUP</div><section class="panel"><h1 class="panel-title">🏆 JOVENRA TROPHY</h1><p class="panel-desc">Three consecutive local computer duels. Win each round to take home the cup.</p><div class="cup-rounds">${['BRONZE DUEL','SILVER SHOWDOWN','GOLD FINAL'].map((name,i)=>`<div class="cup-round"><span>${['🥉','🥈','🥇'][i]}</span><b>ROUND ${i+1}</b><strong>${name}</strong></div>`).join('')}</div><p class="helper">Your progress is saved locally after each win. Online tournaments are not included.</p><div class="cta-row"><button class="btn-primary" data-action="cup-start">START CUP ➜</button></div><div class="center note">Cups earned: ${records.cups}</div></section></main>${footer()}</div>`}
function daily(){const today=new Date().toLocaleDateString('en-CA');const claimed=records.lastClaim===today;return `<div class="scene">${header()}<main class="screen-main"><div class="back-nav"><button data-action="home">‹ BACK</button> DAILY BONUS</div><section class="panel bonus-panel"><h1 class="panel-title">🌟 DAILY STAR</h1><div class="bonus-star">✦</div><p class="panel-desc">Come back daily to collect a free star. No ads and no purchases required.</p><div class="daily-stats"><span><b>${records.stars}</b><small>TOTAL STARS</small></span><span><b>${records.streak}</b><small>DAY STREAK</small></span></div><div class="cta-row"><button class="btn-primary" data-action="claim-daily" ${claimed?'disabled':''}>${claimed?'✓ CLAIMED TODAY':'COLLECT TODAY’S STAR'}</button></div><p class="helper">Stars are local milestones and have no monetary value.</p></section></main>${footer()}</div>`}
function achievements(){return `<div class="scene">${header()}<main class="screen-main"><div class="back-nav"><button data-action="home">‹ BACK</button> MY BADGES</div><section class="panel"><h1 class="panel-title">YOUR TROPHY SHELF</h1><p class="panel-desc">Saved only in this browser. No account is needed.</p><div class="achievement-stats"><span><b>${records.wins}</b> GAME WINS</span><span><b>${records.cups}</b> TROPHY CUPS</span><span><b>${records.stars}</b> DAILY STARS</span></div><div class="challenge-grid">${CHALLENGES.map(c=>`<div class="challenge-card ${records.completed.includes(c.id)?'medal-earned':'medal-locked'}"><span class="challenge-icon">${c.icon}</span><span class="challenge-detail"><b>${c.name}</b><small>${records.completed.includes(c.id)?'Achievement earned!':'Complete this local challenge to unlock.'}</small><em>${records.completed.includes(c.id)?'★ UNLOCKED':'☆ LOCKED'}</em></span></div>`).join('')}</div><div class="cta-row"><button class="btn-primary" data-action="challenges">TRY CHALLENGES ➜</button></div></section></main>${footer()}</div>`}
function boardCell(r,c){const base=r<6?(c<6?'red':c>=9?'green':null):r>=9?(c<6?'blue':c>=9?'yellow':null):null;let track='';
  if(r===7&&c>0&&c<6)track='red';if(c===7&&r>0&&r<6)track='green';if(r===7&&c>=9&&c<14)track='yellow';if(c===7&&r>=9&&r<14)track='blue';
  // Along the 52-cell outside path, only the color start tile is filled.
  for(let p=0;p<4;p++){const q=PATH[START_INDEX[p]];if(q[0]===r&&q[1]===c)track=COLORS[p]}
  const pathIdx=PATH.findIndex(([a,b])=>a===r&&b===c),safe=SAFE.has(pathIdx);
  return `<div class="board-cell ${base?'corner-'+base:''} ${track?'track-'+track:''} ${pathIdx>=0&&[0,13,26,39].includes(pathIdx)?'start-cell':''}" style="grid-row:${r+1};grid-column:${c+1}">${safe?'<span class="safe-star">☆</span>':''}</div>`;
}
function baseHtml(color){return `<div class="board-base base-${color}"><div class="base-inner">${Array.from({length:4},()=>'<i class="base-ring"></i>').join('')}</div></div>`}
function pawnMarkup(g){const counts=new Map(),all=[];const valid=legalMoves(g);for(let p=0;p<4;p++){if(g.types[p]==='off')continue;for(let i=0;i<4;i++){const pos=tokenLocation(p,g.tokens[p][i],i),key=pos.join(',');counts.set(key,(counts.get(key)||0)+1);all.push({p,i,pos,key});}}
 const counters=new Map();return all.map(t=>{const n=counters.get(t.key)||0; counters.set(t.key,n+1);const tally=counts.get(t.key)||1;const ready=!rolling&&!moving&&g.phase==='move'&&t.p===g.current&&valid.includes(t.i);const dx=tally===1?0:(n%2?1:-1)*8,dy=tally===1?0:(n>1?5:-5);return `<button class="token-anchor ${ready?'available':''}" data-token="${t.p}:${t.i}" aria-label="${labels[t.p]} token ${t.i+1}${ready?', move now':''}" style="left:calc(${(t.pos[1]+.5)*100/15}% + ${dx}px);top:calc(${(t.pos[0]+.5)*100/15}% + ${dy}px)" ${ready?'':'disabled'}>${pawn(COLORS[t.p])}</button>`}).join('')}
function boardHtml(g){let squares='';for(let r=0;r<15;r++)for(let c=0;c<15;c++)squares+=boardCell(r,c);return `<div class="board-mat"><div class="ludo-board" id="ludo-board">${squares}${COLORS.map(baseHtml).join('')}<div class="board-center"></div><span class="board-arrow up">↑</span><span class="board-arrow down">↓</span><span class="board-arrow left">←</span><span class="board-arrow right">→</span><span class="player-name top">${g.types[1]==='off'?'':g.types[1]==='human'?'You':'Computer'}</span><span class="player-name bottom">${g.types[3]==='off'?'':g.types[3]==='human'?'You':'Computer'}</span>${pawnMarkup(g)}</div></div>`}
function namesFor(g){const humans=activePlayers(g).filter(p=>g.types[p]==='human');const bots=activePlayers(g).filter(p=>g.types[p]==='bot');return {human:humans[0]??3,bot:bots[0]??1}}
function match(){const g=game;const players=activePlayers(g);const self=selection.color;const current=g.current;const isHuman=g.types[current]==='human';const others=players.filter(p=>p!==self);const who= current===self?'YOUR TURN':g.types[current]==='bot'?'COMPUTER TURN':`${labels[current].toUpperCase()} TURN`;
 return `<div class="scene game-scene">${header(true)}<main class="game-layout"><section class="board-col"><div class="match-heading"><span><strong class="match-label">${(challengeId==='cup'?'CUP ROUND '+trophyRound:selection.mode.toUpperCase())} · ${players.length} PLAYERS</strong><span class="match-sub">${selection.kind==='computer'?'You vs computer':'Pass and play'} · Round ${g.turn}</span></span><span class="match-turn">● ${who}</span></div>${boardHtml(g)}<div class="turn-toast" id="turn-toast">${g.lastEvent}</div></section><section class="match-side"><div class="panel"><div class="score-header">PLAYERS</div><div class="score-players">${players.slice(0,4).map((p,i)=>`<div class="score-person"><div class="avatar ${COLORS[p]}">${g.types[p]==='bot'?'🤖':'🙂'}</div><b>${p===self?'You':g.types[p]==='bot'?'Com':labels[p]}</b><small>${g.tokens[p].filter(n=>n===56).length}/4 home</small></div>${i===0&&players.length===2?'<div class="score-vs">VS</div>':''}`).join('')}</div></div><div class="panel dice-desk"><div class="score-header">${who}</div><div class="roll-box"><div class="dice-shadow"></div>${dieHtml(dieValue)}<div class="roll-result" id="dice-status">${rolling?'ROLLING…':lastRoll?`LAST ROLL · ${lastRoll}`:'TAP TO ROLL'}</div><button class="blue-button" data-action="roll" ${!canRoll()?'disabled':''}>${rolling?'ROLLING…':g.phase==='move'?'CHOOSE A TOKEN':g.types[g.current]==='bot'?'COMPUTER THINKING':'ROLL DICE ⚄'}</button></div></div><div class="panel"><div class="score-header">MATCH EVENTS</div><div class="activity">${g.lastEvent}</div><div class="quick-status">${MODE_GOALS[selection.mode]||'All four home to win'}</div></div></section></main><nav class="bottom-dock"><div class="dock-label">${g.types[current]==='human'?'You':g.types[current]==='bot'?'Com':labels[current]}<small>${who}</small></div><div class="dock-roll"><div class="dock-die">${dieHtml(dieValue)}</div><button class="dock-action" data-action="roll" ${!canRoll()?'disabled':''}>${rolling?'ROLLING…':g.phase==='move'?'MOVE TOKEN':g.types[current]==='bot'?'COM TURN':'ROLL ⚄'}</button></div><div class="dock-label">${others.length===1?(g.types[others[0]]==='bot'?'Com':labels[others[0]]):`${players.length} PLAYERS`}<small>${lastRoll?`ROLL ${lastRoll}`:'READY'}</small></div></nav>${tipVisible?'<div class="tutorial-bubble"><button data-action="close-tip">×</button>Roll a six to bring a token onto the board. Tap glowing tokens to move!</div>':''}${footer()}</div>`;
}
function overlay(){if(!dialog)return '';const close='<button class="close-x" data-action="close-dialog" aria-label="Close dialog">×</button>';
 if(dialog==='pause')return `<div class="overlay"><section class="dialog" role="dialog" aria-modal="true">${close}<h2>GAME PAUSED</h2><div class="dialog-symbol">⏸</div><p>Take a break, or return to the game.</p><div class="dialog-actions"><button class="btn-secondary" data-action="resume-dialog">RESUME</button><button class="btn-secondary" data-action="quit-ask">QUIT GAME</button></div></section></div>`;
 if(dialog==='quit')return `<div class="overlay"><section class="dialog" role="dialog" aria-modal="true">${close}<h2>QUIT GAME?</h2><div class="dialog-symbol">🎲</div><p>Your unfinished match can be continued later.</p><div class="dialog-actions"><button class="btn-secondary" data-action="quit-yes">YES, EXIT</button><button class="btn-primary" data-action="close-dialog">NO, PLAY</button></div></section></div>`;
 if(dialog==='settings')return `<div class="overlay"><section class="dialog" role="dialog" aria-modal="true">${close}<h2>GAME SETTINGS</h2><div class="settings-row"><span>♫ Background music</span><button class="switch ${music?'on':''}" data-action="audio">${music?'ON':'OFF'}</button></div><div class="settings-row settings-slider"><label for="music-volume">♫ Music volume</label><input id="music-volume" aria-label="Music volume" type="range" min="0" max="100" value="${Math.round(musicVolume*100)}" data-music-volume><b id="music-volume-label">${Math.round(musicVolume*100)}%</b></div><div class="settings-row"><span>🔊 Dice & pawn sounds</span><button class="switch ${effects?'on':''}" data-action="sfx">${effects?'ON':'OFF'}</button></div><div class="dialog-actions"><button class="btn-primary" data-action="close-dialog">DONE</button></div></section></div>`;
 if(dialog==='win')return `<div class="overlay"><section class="dialog" role="dialog" aria-modal="true"><div class="celebration">🏆</div><h2>${game.winner===selection.color?'YOU WIN!':`${labels[game.winner].toUpperCase()} WINS!`}</h2><p>${challengeId==='cup'?game.winner!==selection.color?'Cup round lost. Retry this round to advance.':trophyRound>=3?'The Jovenra Cup is yours!':'Round won! Move on to the next cup duel.':challengeId?(game.winner===selection.color?'Challenge completed! Your medal is recorded locally.':'Try again to earn this challenge medal.'):'What a match! Play another round or return to the lobby.'}</p><div class="dialog-actions">${challengeId==='cup'&&trophyRound<3&&game.winner===selection.color?'<button class="btn-primary" data-action="next-round">NEXT ROUND ➜</button>':'<button class="btn-primary" data-action="play-again">PLAY AGAIN</button>'}<button class="btn-secondary" data-action="quit-yes">HOME</button></div></section></div>`;
 return ''}
function paint(){root.innerHTML=(view==='splash'?splash():view==='lobby'?lobby():view==='setup'?selectMode():view==='color'?selectColor():view==='guide'?guide():view==='challenges'?challenges():view==='cup'?trophy():view==='daily'?daily():view==='achievements'?achievements():match())+overlay();}
function save(){if(game){try{localStorage.setItem(KEY,JSON.stringify({game,selection,dieValue,lastRoll,tipShown,challengeId,trophyRound}));}catch{}saved={game,selection,dieValue,lastRoll,tipShown};}}
function savePrefs(){try{localStorage.setItem('jovenra:ludo:preferences',JSON.stringify({music,effects,musicVolume}));}catch{}}
function typesFor(){const types=Array(4).fill('off');types[selection.color]='human';if(selection.players===4){for(let i=0;i<4;i++)if(i!==selection.color)types[i]=selection.kind==='computer'?'bot':'human';}else{types[(selection.color+2)%4]=selection.kind==='computer'?'bot':'human';}return types;}
function newMatch(){game=newGame(typesFor());game.current=selection.color;if(selection.mode==='quick'){/* Same fair start; victory is awarded at first token home. */}view='match';dialog='';dieValue=1;lastRoll=null;rolling=moving=false;tipVisible=!tipShown;tipShown=true;save();paint();scheduleBot();}
function canRoll(){return !!game&&!rolling&&!moving&&!dialog&&game.phase==='roll'&&game.winner===null&&game.types[game.current]==='human'}
function randomDie(){if(qaNext!=null){const x=qaNext;qaNext=null;return x;}if(globalThis.crypto?.getRandomValues){const a=new Uint32Array(1);let n;const limit=Math.floor(4294967296/6)*6;do{crypto.getRandomValues(a);n=a[0]}while(n>=limit);return n%6+1;}return Math.floor(Math.random()*6)+1}
// Original Web Audio sound effects: timed clacks and soft synth, no third-party music or recordings.
let ac=null;const soundtrack=new Audio('data:audio/mpeg;base64,');soundtrack.preload='auto';soundtrack.loop=true;soundtrack.volume=musicVolume;soundtrack.setAttribute('playsinline','');
function audioContext(){try{if(!ac)ac=new(window.AudioContext||window.webkitAudioContext)();if(ac.state==='suspended')ac.resume();return ac}catch{return null}}
function blip(freq=450,seconds=.1,volume=.07,type='sine',delay=0){const c=audioContext();if(!c||!effects)return;const o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,c.currentTime+delay);o.frequency.exponentialRampToValueAtTime(Math.max(80,freq*.72),c.currentTime+delay+seconds);g.gain.setValueAtTime(.0001,c.currentTime+delay);g.gain.exponentialRampToValueAtTime(volume,c.currentTime+delay+.007);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+delay+seconds);o.connect(g).connect(c.destination);o.start(c.currentTime+delay);o.stop(c.currentTime+delay+seconds+.03)}
function clack(strength=.6,delay=0){const c=audioContext();if(!c||!effects)return;const sampleRate=c.sampleRate,length=Math.floor(.085*sampleRate),buffer=c.createBuffer(1,length,sampleRate),s=buffer.getChannelData(0);for(let i=0;i<length;i++){const decay=Math.pow(1-i/length,5);s[i]=(Math.random()*2-1)*decay;}const src=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain();src.buffer=buffer;filter.type='bandpass';filter.frequency.value=1300+Math.random()*1200;gain.gain.value=strength*.18;src.connect(filter).connect(gain).connect(c.destination);src.start(c.currentTime+delay)}
function diceSounds(){for(let i=0;i<10;i++)clack(.5+(i%3)*.10,i*.095);clack(.9,1.05);blip(260,.16,.045,'triangle',1.09)}
function hopSound(){blip(420+Math.random()*100,.09,.055,'sine');clack(.18,.07)}
function menuSound(){blip(610,.1,.04,'sine')}
function beginMusic(){
 if(!music||!ambientStarted||document.hidden)return;
 soundtrack.volume=musicVolume;
 // Must be called directly from a user gesture when first starting (Chrome/iOS autoplay policy).
 const pending=soundtrack.play();if(pending?.catch)pending.catch(()=>{ /* Browser denied autoplay; next tap will retry. */ });
}
function stopMusic(){soundtrack.pause()}
function setMusicVolume(level){musicVolume=Math.max(0,Math.min(1,level));soundtrack.volume=musicVolume;savePrefs();const label=document.querySelector('#music-volume-label');if(label)label.textContent=Math.round(musicVolume*100)+'%'}
function rollStart(){if(!game||game.phase!=='roll'||rolling||moving||dialog)return;rolling=true;const target=randomDie();const origin=dieValue;paint();diceSounds();const cubes=[...root.querySelectorAll('.die-cube')];const bouncers=[...root.querySelectorAll('.die-bouncer')];const shadows=[...root.querySelectorAll('.dice-shadow')];
 const [ax,ay]=angles[origin],[bx,by]=angles[target];const duration=reduced?15:1390;
 // Three independent rotations and momentum decay; last frame exactly equals the permanent target face.
 const k=[];for(let i=0;i<=28;i++){const t=i/28,spin=1-Math.pow(1-t,2.0);const x=ax+(1080+bx-ax)*spin;const y=ay+(1080+by-ay)*spin;const z=720*spin; k.push({transform:`rotateX(${x}deg) rotateY(${y}deg) rotateZ(${z}deg)`,offset:t})}
 const flights=[{transform:'translate(0,0) scale(1)',offset:0},{transform:'translate(-17px,-18px) scale(1.06)',offset:.13},{transform:'translate(-11px,-42px) scale(1.13)',offset:.27},{transform:'translate(15px,-26px) scale(1.07)',offset:.42},{transform:'translate(23px,-5px) scale(.96)',offset:.56},{transform:'translate(5px,-23px) scale(1.05)',offset:.69},{transform:'translate(-9px,-3px) scale(.98)',offset:.82},{transform:'translate(3px,-7px) scale(1.02)',offset:.92},{transform:'translate(0,0) scale(1)',offset:1}];
 const animations=[];for(const cube of cubes)animations.push(cube.animate(k,{duration,easing:'linear',fill:'forwards'}));for(const e of bouncers)animations.push(e.animate(flights,{duration,easing:'linear',fill:'forwards'}));for(const sh of shadows)animations.push(sh.animate([{transform:'scale(1)',opacity:.7},{transform:'scale(.6)',opacity:.25,offset:.3},{transform:'scale(.9)',opacity:.5,offset:.7},{transform:'scale(1)',opacity:.7}],{duration,fill:'forwards'}));
 Promise.all(animations.map(a=>a.finished.catch(()=>{}))).then(async()=>{if(!game||view!=='match')return;for(const cube of cubes)cube.style.transform=diceTransform(target);for(const a of animations)a.cancel();dieValue=target;lastRoll=target;game=roll(game,target);rolling=false;save();paint();if(game.winner!==null){dialog='win';paint()}else if(game.phase==='move'&&game.types[game.current]==='human'){const valid=legalMoves(game);if(valid.length===1){setTimeout(()=>{if(game?.phase==='move'&&!moving)movePawn(valid[0])},420)}}scheduleBot();});
}
async function movePawn(tokenIndex){if(!game||game.phase!=='move'||rolling||moving||dialog||!legalMoves(game).includes(tokenIndex))return;moving=true;const p=game.current,prev=game.tokens[p][tokenIndex],steps=prev===-1?1:game.dice;const board=root.querySelector('#ludo-board'),original=root.querySelector(`[data-token="${p}:${tokenIndex}"]`);if(original)original.style.visibility='hidden';let movingToken=null;
 if(board){movingToken=document.createElement('span');movingToken.className='token-anchor moving-pawn';movingToken.innerHTML=pawn(COLORS[p]);board.append(movingToken)}
 for(let s=1;s<=steps;s++){if(!movingToken||!board)break;const from=tokenLocation(p,prev===-1?-1:prev+s-1,tokenIndex),to=tokenLocation(p,prev===-1?0:prev+s,tokenIndex);const c=board.getBoundingClientRect(),u=c.width/15,dx=(to[1]-from[1])*u,dy=(to[0]-from[0])*u;
  movingToken.style.left=`${(from[1]+.5)/15*100}%`;movingToken.style.top=`${(from[0]+.5)/15*100}%`;const a=movingToken.animate([{transform:'translate(-50%,-50%) translate(0px,0px) scale(1)'},{transform:`translate(-50%,-50%) translate(${dx*.47}px,${dy*.47-15}px) scale(1.17)`,offset:.47},{transform:`translate(-50%,-50%) translate(${dx}px,${dy}px) scale(.9)`,offset:.88},{transform:`translate(-50%,-50%) translate(${dx}px,${dy}px) scale(1)`}],{duration:reduced?10:245,easing:'ease-in-out',fill:'forwards'});hopSound();await a.finished.catch(()=>{});a.cancel();movingToken.style.left=`${(to[1]+.5)/15*100}%`;movingToken.style.top=`${(to[0]+.5)/15*100}%`;await wait(reduced?0:35);
 }
 const old=game,was=old.tokens[p][tokenIndex],hadCapture=(old.dice!=null&& old.dice!==6);game=resolveMove(game,tokenIndex);if(selection.mode==='quick'){if(game.tokens[p].some(x=>x===56)){game.winner=p;game.phase='finished';game.lastEvent=`${labels[p]} wins the quick match!`}}
 if(game.lastEvent.includes('captured'))game.hasCaptured=game.hasCaptured||{} ,game.hasCaptured[p]=true;
 if(selection.mode==='capture'&&game.lastEvent.includes('captured')){game.winner=p;game.phase='finished'}
 if(selection.mode==='popular'&&game.tokens[p].filter(x=>x===56).length>=2){game.winner=p;game.phase='finished';game.lastEvent=`${labels[p]} wins the popular match!`}
 if(selection.mode==='mask'&&game.hasCaptured?.[p]&&game.tokens[p].some(x=>x===56)){game.winner=p;game.phase='finished';game.lastEvent=`${labels[p]} completed the mystery challenge!`}
 moving=false;if(game.winner!==null)recordVictory();save();paint();if(game.winner!==null){dialog='win';paint()}else scheduleBot();
}
function recordVictory(){if(game?.winner!==selection.color)return;records.wins++;if(challengeId==='cup'&&trophyRound===3)records.cups++;if(challengeId&&challengeId!=='cup'&&!records.completed.includes(challengeId))records.completed.push(challengeId);saveRecords()}
function scheduleBot(){clearTimeout(botTimer);if(!game||view!=='match'||dialog||rolling||moving||game.winner!==null||game.types[game.current]!=='bot')return;botTimer=setTimeout(()=>{if(view!=='match'||!game||rolling||moving||dialog||game.types[game.current]!=='bot')return;if(game.phase==='roll')rollStart();else{const t=chooseBotMove(game);if(t!=null)movePawn(t)}},550)}
function home(){clearTimeout(botTimer);dialog='';view='lobby';rolling=false;moving=false;paint()}
function toggleAudio(){music=!music;ambientStarted=true;savePrefs();if(music)beginMusic();else stopMusic();paint()}
function toggleSfx(){effects=!effects;savePrefs();paint()}
function startFromSaved(){if(!saved)return;({game,selection,dieValue,lastRoll,tipShown}=saved);challengeId=saved.challengeId||null;trophyRound=saved.trophyRound||0;dialog='';view='match';rolling=moving=false;tipVisible=false;paint();scheduleBot()}
root.addEventListener('click',e=>{const tok=e.target.closest('[data-token]');if(tok){if(!ambientStarted){ambientStarted=true;beginMusic()}if(game?.types[game.current]==='human'){const [p,t]=tok.dataset.token.split(':').map(Number);if(p===game.current)movePawn(t)}return}const opt=e.target.closest('[data-option]');if(opt){if(!ambientStarted){ambientStarted=true;beginMusic()}menuSound();const [k,v]=opt.dataset.option.split(':');if(k==='players')selection.players=Number(v);if(k==='mode')selection.mode=v;if(k==='color')selection.color=Number(v);paint();return}
 const challenge=e.target.closest('[data-challenge]')?.dataset.challenge;if(challenge){if(!ambientStarted){ambientStarted=true;beginMusic()}const chosen=CHALLENGES.find(c=>c.id===challenge);if(chosen){challengeId=chosen.id;trophyRound=0;selection={kind:'computer',players:2,mode:chosen.mode,color:3};view='color';menuSound();paint()}return}
 const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(!ambientStarted){ambientStarted=true;beginMusic()}menuSound();switch(action){case 'home':if(view==='match'){dialog='quit'}else home();break;case 'computer':challengeId=null;trophyRound=0;selection.kind='computer';selection.mode='classic';view='setup';break;case 'pass':challengeId=null;trophyRound=0;selection.kind='pass';selection.mode='classic';view='setup';break;case 'challenges':view='challenges';break;case 'cup':view='cup';break;case 'cup-start':challengeId='cup';trophyRound=1;selection={kind:'computer',players:2,mode:'quick',color:3};view='color';break;case 'next-round':trophyRound=Math.min(3,trophyRound+1);dialog='';newMatch();return;case 'daily':view='daily';break;case 'achievements':view='achievements';break;case 'claim-daily':{const today=new Date().toLocaleDateString('en-CA');if(records.lastClaim!==today){const prev=new Date();prev.setDate(prev.getDate()-1);const yesterday=prev.toLocaleDateString('en-CA');records.streak=records.lastClaim===yesterday?records.streak+1:1;records.stars++;records.lastClaim=today;saveRecords();}break;}case 'guide':view='guide';break;case 'back-mode':view='setup';break;case 'next-color':view='color';break;case 'start':newMatch();return;case 'resume':startFromSaved();return;case 'pause':dialog='pause';break;case 'quit-ask':dialog='quit';break;case 'quit-yes':home();return;case 'resume-dialog':case 'close-dialog':dialog='';break;case 'settings':dialog='settings';break;case 'audio':toggleAudio();return;case 'sfx':toggleSfx();return;case 'roll':if(canRoll())rollStart();return;case 'close-tip':tipVisible=false;break;case 'play-again':newMatch();return;}paint()});
root.addEventListener('input',e=>{if(e.target.matches('[data-music-volume]'))setMusicVolume(Number(e.target.value)/100)});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog){dialog='';paint();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopMusic();else if(ambientStarted&&music)beginMusic()});
if(!location.hostname||['localhost','127.0.0.1'].includes(location.hostname)){window.__ludoQA={setRoll(v){if(v<1||v>6)throw Error('Dice must be 1–6');qaNext=v},seedMatch(patch){if(!game)throw Error('No match');if(patch.tokens)game.tokens=patch.tokens;if(patch.current!=null)game.current=patch.current;if(patch.phase)game.phase=patch.phase;if(patch.hasCaptured)game.hasCaptured=patch.hasCaptured;game.dice=null;game.winner=null;rolling=false;moving=false;dialog='';paint()},getState(){return {view,dialog,game,dieValue,lastRoll,rolling,moving,selection,challengeId,trophyRound}},audio(){return {paused:soundtrack.paused,readyState:soundtrack.readyState,currentTime:soundtrack.currentTime,volume:soundtrack.volume,duration:soundtrack.duration,src:soundtrack.currentSrc.slice(0,30)}},advance(){if(view==='splash'){view='lobby';paint()}}}};
paint();setTimeout(()=>{if(view==='splash'){view='lobby';paint()}},750);
